-- =============================================================================
-- sql/security-hardening.sql — Security Notes & Hardening
-- Generated by SQL Audit (2026-04-05)
-- =============================================================================
--
-- IMPORTANT: This project uses SQLite, NOT PostgreSQL/Supabase.
-- Several security features available in PostgreSQL are not available in SQLite:
--
--   ❌ Row-Level Security (RLS)        — PostgreSQL-only
--   ❌ SECURITY DEFINER functions       — PostgreSQL-only
--   ❌ pg_cron scheduled jobs           — PostgreSQL extension
--   ❌ Column-level privileges          — PostgreSQL-only
--
-- SQLite security is enforced at the application layer (server.ts).
-- The fixes below are what SQLite DOES support.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. FOREIGN KEY ENFORCEMENT
-- SQLite does NOT enforce foreign keys by default.
-- Fix applied in server.ts (line after db init):
--   db.pragma("foreign_keys = ON");
--
-- To verify at runtime:
PRAGMA foreign_keys; -- Should return 1

-- -----------------------------------------------------------------------------
-- 2. WAL MODE (Write-Ahead Logging)
-- Improves concurrent read performance and crash recovery.
-- Safe to enable on existing databases.
PRAGMA journal_mode = WAL;

-- -----------------------------------------------------------------------------
-- 3. SYNCHRONOUS MODE
-- NORMAL offers good performance + crash safety with WAL.
-- (Default is FULL which is slower; OFF is dangerous)
PRAGMA synchronous = NORMAL;

-- -----------------------------------------------------------------------------
-- 4. MISSING CONSTRAINTS — Cannot alter existing tables in SQLite.
-- For a fresh schema, add these CHECK constraints to CREATE TABLE:
--
-- users:
--   money INTEGER DEFAULT 1000 CHECK(money >= 0)
--   energy INTEGER DEFAULT 100 CHECK(energy >= 0 AND energy <= 100)
--   level INTEGER DEFAULT 1 CHECK(level >= 1)
--   perkPoints INTEGER DEFAULT 0 CHECK(perkPoints >= 0)
--
-- regions:
--   stability INTEGER DEFAULT 100 CHECK(stability >= 0 AND stability <= 100)
--   resources INTEGER DEFAULT 50 CHECK(resources >= 0)
--   taxes INTEGER DEFAULT 10 CHECK(taxes >= 0 AND taxes <= 100)
--
-- factories:
--   payoutMoney INTEGER CHECK(payoutMoney > 0)
--   energyCost INTEGER CHECK(energyCost > 0)
--   cooldownSec INTEGER CHECK(cooldownSec > 0)
--   minLevel INTEGER DEFAULT 1 CHECK(minLevel >= 1)
--
-- wars:
--   attackerScore INTEGER DEFAULT 0 CHECK(attackerScore >= 0)
--   defenderScore INTEGER DEFAULT 0 CHECK(defenderScore >= 0)
--   status TEXT CHECK(status IN ('active', 'ended'))
--
-- NOTE: To apply these constraints on an existing database you would need to:
--   1. Create new table with constraints
--   2. INSERT INTO new_table SELECT * FROM old_table
--   3. DROP TABLE old_table; ALTER TABLE new_table RENAME TO old_table;
-- Not applied automatically to avoid disrupting existing data.

-- -----------------------------------------------------------------------------
-- 5. CRITICAL ISSUES — Must be fixed in application code (not SQL):
--
-- [CRITICAL] Plaintext passwords
--   Location: server.ts POST /api/register + POST /api/login
--   Risk: Full credential exposure if database file is accessed
--   Fix: Use bcrypt — npm install bcrypt @types/bcrypt
--     Register: password = await bcrypt.hash(password, 12)
--     Login:    valid   = await bcrypt.compare(plaintext, user.password)
--   Note: Requires one-time migration to re-hash existing passwords on next login
--         (or a reset-password flow)
--
-- [CRITICAL] No article content length limits
--   Location: server.ts POST /api/articles, PUT /api/articles/:id
--   Risk: DoS via 100MB article payloads filling disk
--   Fix:
--     if (title.length > 200 || content.length > 50000)
--       return res.status(400).json({ error: "Content too long" });
--
-- [LOW] Random IDs via Math.random()
--   Location: server.ts (user/war/article IDs)
--   Risk: Predictable IDs — 7-char base36 = ~78 billion combinations,
--         acceptable for MVP but upgrade to crypto.randomUUID() for production
--   Fix: const id = crypto.randomUUID();  (built-in Node.js 14.17+)

-- =============================================================================
-- END security-hardening.sql
-- =============================================================================
